/**
 * Arri RPC API Client for Avatar Creator
 * Connects to the Python Arri RPC backend using the autogenerated AvatarArriClient.
 */

import {
  AvatarArriClient,
  type GenerateAvatarParams,
  type GenerateAvatarResponse,
  type GetAvatarStatusParams,
  type GetAvatarStatusResponse,
  type GetVramStatusResponse,
} from "./arri_client.rpc";

const BACKEND_URL =
  import.meta.env.VITE_BACKEND_URL || "http://localhost:5000";

// Instantiate the strongly-typed Arri RPC Client
export const arriClient = new AvatarArriClient({
  baseUrl: BACKEND_URL,
});

/**
 * Executes the 8-step AI Avatar generation pipeline via Arri RPC
 */
export async function generateAvatar(
  imageData: string,
  filename: string = "portrait.jpg",
  characterStyle: string = "pixar_3d",
  meshQuality: string = "high"
): Promise<GenerateAvatarResponse> {
  const params: GenerateAvatarParams = {
    imageData,
    filename,
    characterStyle,
    meshQuality,
  };
  return await arriClient.avatar.generate(params);
}

/**
 * Polls status and telemetry of an ongoing avatar creation job
 */
export async function getAvatarStatus(
  jobId: string
): Promise<GetAvatarStatusResponse> {
  const params: GetAvatarStatusParams = { jobId };
  return await arriClient.avatar.getStatus(params);
}

/**
 * Queries current GPU VRAM utilization on RTX 3060 12GB
 */
export async function getVramStatus(): Promise<GetVramStatusResponse> {
  return await arriClient.avatar.getVramStatus({});
}

